const angVal = document.getElementById('angVal');
let programmatic = false;

function setAngle(v, fromDemo) {
  axisAngleDeg = v;
  slider.value = String(Math.round(v));
  angVal.textContent = v.toFixed(0) + '°';
  updateAxisGeometry();
  updateSelection();
  if (!fromDemo && panel !== 'b') setPanel('b');
}

slider.addEventListener('input', () => { if (!programmatic) setAngle(parseFloat(slider.value), false); });
document.getElementById('btnA').addEventListener('click', () => { selected = -1; setPanel('a'); });
document.getElementById('btnB').addEventListener('click', () => { setPanel('b'); });
document.getElementById('btnClear').addEventListener('click', () => { selected = -1; updateSelection(); });
document.getElementById('chkPlane').addEventListener('change', (e) => { planeHint.visible = e.target.checked; });

/* ── guided demo ─────────────────────────────────────────────────────────── */
const steps = [
  { title: '1 · Unpolarized light',
    text: 'A ray travels from upper left to lower right. Eight red E arrows radiate from a point on it, all perpendicular to the ray and equally likely — random (unpolarized) polarization.',
    panel: 'a', angle: 0, sel: -1 },
  { title: '2 · Insert the polarizing filter',
    text: 'A tan filter disk is placed across the ray. Its transmission axis — the black double-headed arrow — is vertical. Downstream only one red arrow remains, vertical like the axis.',
    panel: 'b', angle: 0, sel: -1 },
  { title: '3 · Rotate the axis',
    text: 'Turning the filter axis to 45° turns the transmitted E arrow to 45° as well: the filter, not the source, chooses the polarization direction.',
    panel: 'b', angle: 45, sel: -1 },
  { title: '4 · One incident direction at a time',
    text: 'Click any incoming red arrow: it splits into a component along the axis (passes, drawn bold) and a component across it (faded, absorbed). Transmitted length ∝ |cos θ|.',
    panel: 'b', angle: 45, sel: 1 }
];
let stepIdx = 0;
let tweenId = null;

function tweenAngle(target) {
  if (tweenId) cancelAnimationFrame(tweenId);
  const start = axisAngleDeg, t0 = performance.now(), dur = 650;
  if (Math.abs(target - start) < 0.01) { setAngle(target, true); return; }
  (function frame() {
    const k = Math.min(1, (performance.now() - t0) / dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    programmatic = true;
    setAngle(start + (target - start) * e, true);
    programmatic = false;
    if (k < 1) tweenId = requestAnimationFrame(frame); else tweenId = null;
  })();
}

function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const s = steps[stepIdx];
  selected = s.sel;
  setPanel(s.panel);
  tweenAngle(s.angle);
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  document.getElementById('btnPrev').disabled = (stepIdx === 0);
  document.getElementById('btnNext').disabled = (stepIdx === steps.length - 1);
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── initial state: geometry first, then camera, then labels/interactions ── */
updateAxisGeometry();
setPanel('a');                                  // calls frameFor → setCameraView

// keep the figure recognisable while still allowing exploratory orbiting
const baseAz = Math.PI / 4, basePol = Math.acos(1 / Math.sqrt(3));
controls.minAzimuthAngle = baseAz - Math.PI / 3;
controls.maxAzimuthAngle = baseAz + Math.PI / 3;
controls.minPolarAngle = Math.max(0.05, basePol - Math.PI / 4);
controls.maxPolarAngle = Math.min(Math.PI - 0.05, basePol + Math.PI / 4);

goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;font-size:12px;margin-bottom:2px">Polarization of light</div>

<div style="font-weight:600;margin-top:4px">View</div>
<button id="btnA" class="active">(a) Unpolarized ray</button>
<button id="btnB">(b) Ray through polarizing filter</button>
<button id="btnFace">Look down the ray (face-on)</button>

<label style="margin-top:6px">Filter axis angle (0° = vertical, + = CCW): <b id="angVal">0°</b>
  <input id="axisAngle" type="range" min="-90" max="90" step="5" value="0">
</label>

<div style="margin-top:6px;line-height:1.35">
  <b>Click</b> any red incident <i>E</i> arrow of the starburst to split it into a
  component <i>along</i> the filter axis (passes) and one <i>across</i> it (absorbed).
</div>
<button id="btnClear">Clear selection</button>
<div id="selInfo" style="font-size:11px;color:#333;min-height:14px"></div>

<label style="flex-direction:row;align-items:center;gap:5px;margin-top:4px">
  <input type="checkbox" id="chkPlane"> Show transverse plane
</label>

<hr style="width:100%;border:0;border-top:1px solid #dcdfe3;margin:6px 0">
<div style="font-weight:600">Guided demo</div>
<div id="stepTitle" style="font-weight:600;font-size:11px"></div>
<div id="stepText" style="font-size:11px;line-height:1.35;min-height:52px"></div>
<div style="display:flex;gap:4px">
  <button id="btnPrev">◀ Prev</button>
  <button id="btnNext">Next ▶</button>
</div>

<div style="font-size:10px;color:#555;margin-top:6px;line-height:1.3">
  Drag to orbit: every <i>E</i> arrow stays in the plane perpendicular to the ray —
  the starburst is a transverse disk of directions, not a flat fan.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ───────────────────────────────────────────────────────────
   ray (a) & (b)      → Cylinder(r=0.025) shaft + Cone(0.15,0.5) head, teal #1F7A9B
   starburst x8       → Cylinder(r=0.055) shaft + Cone(0.17,0.42) head, red #C0392B, every 45° ⟂ d
   pick proxies x8    → Cylinder(r=0.32) invisible, for raycasting
   transverse circle  → LineLoop (dashed) r=1.95, faint red, toggle
   filter disk        → Cylinder(1.3,1.3,0.10) tan #F3D2A0 @0.75 DoubleSide
   filter rim         → Torus(1.32,0.05) orange #E09A3E ; inner outline LineLoop r=1.18
   axis indicator     → double-headed arrow, black, total 2.2, in filter plane
   transmitted E      → double-headed arrow, red, total 2.2, ⟂ d, along axis dir
   decomposition      → parallel arrow (solid) + perpendicular arrow (0.15 α) + dashed projections
   leaders            → CubicBezierCurve3 → Line, #1A1A1A (curly)
   all text           → addLabel HTML, #1A1A1A ; E-vector glyph = CSS overbar + CSS arrowhead
──────────────────────────────────────────────────────────────────────────── */

const DEG = Math.PI / 180;
const UP  = new THREE.Vector3(0, 1, 0);

/* ── camera-aligned construction frame ───────────────────────────────────── */
// Default pose is the standard isometric one (axisScreenAngles {30,30}).
const AZ0 = 45 * DEG, EL0 = 35.264389682754654 * DEG;
const CAMDIR = new THREE.Vector3(Math.cos(AZ0) * Math.cos(EL0), Math.sin(EL0), Math.sin(AZ0) * Math.cos(EL0));
const FWD    = CAMDIR.clone().negate();                                  // into the screen
const SRIGHT = new THREE.Vector3(Math.sin(AZ0), 0, -Math.cos(AZ0));      // screen right
const SUP    = new THREE.Vector3().crossVectors(SRIGHT, FWD).normalize();// screen up

// Ray direction: projects on screen as a shallow down-right slant, but keeps a
// large depth component so the transverse plane stays nearly face-on (the eight
// E arrows read as an even 45° star, as printed).
const SLOPE = -18 * DEG, PSCREEN = 0.57;
const D = new THREE.Vector3()
  .addScaledVector(SRIGHT, Math.cos(SLOPE) * PSCREEN)
  .addScaledVector(SUP,    Math.sin(SLOPE) * PSCREEN)
  .addScaledVector(FWD,    Math.sqrt(1 - PSCREEN * PSCREEN))
  .normalize();
const E2v = SUP.clone().addScaledVector(D, -SUP.dot(D)).normalize();   // in-plane "up" (screen-vertical)
const E1v = new THREE.Vector3().crossVectors(D, E2v).normalize();      // in-plane "right"

const RED = 0xC0392B, TEAL = 0x1F7A9B, TAN = 0xF3D2A0, ORNG = 0xE09A3E, INK = '#1A1A1A';
const L_ARROW = 1.7;
const S_FILTER = 5.4, S_TRANS = 9.2;
const RAY_A = [-4.6, 4.6], RAY_B = [-4.0, 13.2];

function P(s, x, y) {
  return new THREE.Vector3()
    .addScaledVector(D, s)
    .addScaledVector(E1v, x || 0)
    .addScaledVector(E2v, y || 0);
}
// phi measured from in-plane "up"; +phi appears CLOCKWISE on screen (D points away).
function inPlane(phi) { return E2v.clone().applyAxisAngle(D, phi); }

const qD  = new THREE.Quaternion().setFromUnitVectors(UP, D);
const qDz = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), D);

/* ── E-vector glyph (reliable overbar + arrowhead, no exotic codepoints) ─── */
function EVEC(px) {
  const bar = Math.max(2, Math.round(px / 8));
  return '<span style="position:relative;display:inline-block;font-style:italic;font-weight:700;'
    + 'line-height:1.05;padding-right:4px">E'
    + '<span style="position:absolute;left:0;right:1px;top:-0.17em;height:' + bar + 'px;background:currentColor"></span>'
    + '<span style="position:absolute;right:-3px;top:-0.36em;width:0;height:0;'
    + 'border-left:5px solid currentColor;border-top:3.5px solid transparent;border-bottom:3.5px solid transparent"></span>'
    + '</span>';
}
const E_GLYPH = EVEC(15);

/* ── builders ────────────────────────────────────────────────────────────── */
function buildArrow(o) {
  const len = o.length;
  const shaftR = o.shaftR ?? 0.055;
  let headLen = o.headLen ?? 0.42, headR = o.headR ?? 0.17;
  if (headLen > len * 0.6) { const k = (len * 0.6) / headLen; headLen *= k; headR *= k; }
  const mat = new THREE.MeshBasicMaterial({ color: o.color, transparent: true, opacity: o.opacity ?? 1 });
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, len, 12), mat);
  shaft.position.y = len / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 18), mat);
  head.position.y = len - headLen / 2;
  g.add(shaft, head);
  g.userData.mat = mat;
  return g;
}

function buildDoubleArrow(o) {
  const mat = new THREE.MeshBasicMaterial({ color: o.color, transparent: true, opacity: o.opacity ?? 1 });
  const shaftR = o.shaftR ?? 0.055, headLen = o.headLen ?? 0.38, headR = o.headR ?? 0.16;
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 12), mat);
  const h1 = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 18), mat);
  const h2 = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 18), mat);
  h2.rotation.z = Math.PI;
  g.add(shaft, h1, h2);
  g.userData.mat = mat;
  g.userData.setLength = function (L) {
    L = Math.max(L, 0.02);
    shaft.scale.y = L;
    h1.position.y =  L / 2 - headLen / 2;
    h2.position.y = -L / 2 + headLen / 2;
  };
  g.userData.setLength(o.length ?? 2.2);
  return g;
}

function orient(obj, dir) { obj.quaternion.setFromUnitVectors(UP, dir.clone().normalize()); }

function buildRay(s0, s1) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: TEAL });
  const headLen = 0.5;
  const len = (s1 - s0) - headLen;
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, len, 8), mat);
  shaft.position.copy(P(s0 + len / 2, 0, 0)); shaft.quaternion.copy(qD);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.15, headLen, 18), mat);
  head.position.copy(P(s1 - headLen / 2, 0, 0)); head.quaternion.copy(qD);
  g.add(shaft, head);
  return g;
}

function makeLeader(p0, p1, bulge) {
  const dir = new THREE.Vector3().subVectors(p1, p0);
  let perp = new THREE.Vector3().crossVectors(dir, D);
  if (perp.lengthSq() < 1e-8) perp = E1v.clone(); else perp.normalize();
  const c1 = p0.clone().addScaledVector(dir, 0.33).addScaledVector(perp,  bulge);
  const c2 = p0.clone().addScaledVector(dir, 0.66).addScaledVector(perp, -bulge);
  const curve = new THREE.CubicBezierCurve3(p0, c1, c2, p1);
  return new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(curve.getPoints(48)),
    new THREE.LineBasicMaterial({ color: 0x1A1A1A })
  );
}

function circleLoop(s, radius, color, opacity, dashed) {
  const pts = [];
  for (let i = 0; i <= 96; i++) {
    const a = (i / 96) * Math.PI * 2;
    pts.push(P(s, radius * Math.cos(a), radius * Math.sin(a)));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  let line;
  if (dashed) {
    line = new THREE.Line(geo, new THREE.LineDashedMaterial({ color, transparent: true, opacity, dashSize: 0.2, gapSize: 0.14 }));
    line.computeLineDistances();
  } else {
    line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color, transparent: true, opacity }));
  }
  return line;
}

/* ── rays ────────────────────────────────────────────────────────────────── */
const rayA = buildRay(RAY_A[0], RAY_A[1]); scene.add(rayA);
const rayB = buildRay(RAY_B[0], RAY_B[1]); scene.add(rayB);

/* ── starburst (8 arrows, every 45°, all transverse) ─────────────────────── */
const starGroup = new THREE.Group(); scene.add(starGroup);
const starArrows = [];
for (let k = 0; k < 8; k++) {
  const dir = inPlane(k * Math.PI / 4);    // k=0 up, 1 up-right, 2 right, 3 down-right, ...
  const arrow = buildArrow({ length: L_ARROW, color: RED, shaftR: 0.055, headLen: 0.42, headR: 0.17 });
  orient(arrow, dir);
  starGroup.add(arrow);

  const proxy = new THREE.Mesh(
    new THREE.CylinderGeometry(0.32, 0.32, L_ARROW, 8),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
  );
  proxy.position.copy(dir.clone().multiplyScalar(L_ARROW / 2));
  orient(proxy, dir);
  starGroup.add(proxy);

  const deg = k * 45;
  registerInteractive(proxy, {
    title: 'Incident E direction, ' + deg + '° from vertical',
    body: 'Unpolarized light contains every transverse E direction. Only the component of this arrow parallel to the filter axis is transmitted; the perpendicular component is absorbed. The transmitted amplitude is |cos θ| of the original.',
    tooltip: 'E at ' + deg + '° — click to resolve into components',
    onClick: () => selectArrow(k)
  });

  starArrows.push({ dir, arrow, mat: arrow.userData.mat, k });
}
const planeHint = circleLoop(0, 1.95, RED, 0.4, true);
planeHint.visible = false;
scene.add(planeHint);

/* ── polarizing filter ───────────────────────────────────────────────────── */
const filterGroup = new THREE.Group(); scene.add(filterGroup);
const disk = new THREE.Mesh(
  new THREE.CylinderGeometry(1.3, 1.3, 0.10, 64),
  new THREE.MeshBasicMaterial({ color: TAN, transparent: true, opacity: 0.75, side: THREE.DoubleSide, depthWrite: false })
);
disk.position.copy(P(S_FILTER, 0, 0)); disk.quaternion.copy(qD);
filterGroup.add(disk);
const rim = new THREE.Mesh(
  new THREE.TorusGeometry(1.32, 0.05, 12, 80),
  new THREE.MeshBasicMaterial({ color: ORNG })
);
rim.position.copy(P(S_FILTER, 0, 0)); rim.quaternion.copy(qDz);
filterGroup.add(rim);
filterGroup.add(circleLoop(S_FILTER + 0.07, 1.18, 0xF6DEB8, 1, false));
registerInteractive(disk, {
  title: 'Polarizing filter',
  body: 'A polarizing filter transmits only the component of the electric field lying along its transmission axis (the black double arrow). Light emerging from it is linearly polarized along that axis.',
  tooltip: 'Polarizing filter — transmits E along its axis'
});

const axisArrow = buildDoubleArrow({ length: 2.2, color: 0x111111, shaftR: 0.022, headLen: 0.18, headR: 0.075 });
axisArrow.position.copy(P(S_FILTER + 0.12, 0, 0));
filterGroup.add(axisArrow);

/* ── transmitted field ───────────────────────────────────────────────────── */
const transGroup = new THREE.Group(); scene.add(transGroup);
const transArrow = buildDoubleArrow({ length: 2.2, color: RED, shaftR: 0.055, headLen: 0.38, headR: 0.16 });
transArrow.position.copy(P(S_TRANS, 0, 0));
transGroup.add(transArrow);

/* ── curly leaders for panel (b) ─────────────────────────────────────────── */
const leadersB = new THREE.Group(); scene.add(leadersB);
leadersB.add(makeLeader(P(S_FILTER, -0.30, 2.85), P(S_FILTER, -0.02, 1.40), 0.22));
leadersB.add(makeLeader(P(S_FILTER,  2.45, 1.60), P(S_FILTER + 0.1, 0.50, 0.95), 0.25));
leadersB.add(makeLeader(P(S_TRANS,   1.60, 2.25), P(S_TRANS, 0.16, 1.20), 0.20));
leadersB.add(makeLeader(P(12.2,      1.60, 1.05), P(12.5, 0.05, 0.12), 0.25));

/* ── selection / decomposition ───────────────────────────────────────────── */
const selGroup = new THREE.Group(); scene.add(selGroup);
let selected = -1;
let axisAngleDeg = 0;
let panel = 'a';
let faceOn = false;

// positive slider angle = counter-clockwise on screen ⇒ negative rotation about D
function axisDir() { return inPlane(-axisAngleDeg * DEG); }

function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const c = g.children[i];
    g.remove(c);
    c.traverse(o => { o.geometry && o.geometry.dispose && o.geometry.dispose(); o.material && o.material.dispose && o.material.dispose(); });
  }
}
function dashedSeg(p0, p1) {
  const l = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([p0, p1]),
    new THREE.LineDashedMaterial({ color: 0x8A3227, dashSize: 0.12, gapSize: 0.08 })
  );
  l.computeLineDistances();
  return l;
}

/* ── labels ──────────────────────────────────────────────────────────────── */
const LBL = [];
function mkLabel(text, pos, opts, grp, faceOk) {
  const e = addLabel(text, pos, opts);
  e.grp = grp; e.faceOk = !!faceOk;
  LBL.push(e);
  return e;
}

const F  = { color: INK, fontSize: '14px' };
const FC = { color: INK, fontSize: '14px' };
const FE = { color: INK, fontSize: '15px' };

/* panel (a) */
mkLabel('Random polarization', P(0, -1.70, 2.45), F, 'a');
mkLabel('Direction of ray<br>(of propagation)', P(0, 0.40, -2.45), F, 'a');
mkLabel('(a)', P(0, 0, -3.65), FC, 'a');
const eOffsets = { 0: [20, -2], 1: [16, -8], 2: [16, -12], 3: [16, 8] };
[0, 1, 2, 3].forEach(k => {
  const p = starArrows[k].dir.clone().multiplyScalar(L_ARROW + 0.30);
  mkLabel(E_GLYPH, p, Object.assign({ offset: eOffsets[k] }, FE), 'a', true);
});

/* panel (b) */
mkLabel(E_GLYPH, starArrows[1].dir.clone().multiplyScalar(L_ARROW + 0.30), Object.assign({ offset: [16, -8] }, FE), 'b', true);
mkLabel('Polarizing filter', P(S_FILTER, -0.35, 3.15), F, 'b');
mkLabel('Axis', P(S_FILTER, 2.80, 1.85), F, 'b');
mkLabel('Polarization<br>direction', P(S_TRANS, 2.05, 2.80), F, 'b');
mkLabel('Direction<br>of ray', P(12.3, 2.05, 1.45), F, 'b');
const eTrans = mkLabel(E_GLYPH, P(S_TRANS, 0.60, -0.55), FE, 'b', true);
mkLabel('(b)', P(4.6, 0, -3.65), FC, 'b');

const selLabel = mkLabel('', P(0, 0.2, -2.55), { color: '#8A3227', fontSize: '12px' }, 'sel', true);

function refreshLabels() {
  LBL.forEach(e => {
    let vis = (e.grp === 'sel') ? (selected >= 0) : (e.grp === panel);
    if (vis && faceOn && !e.faceOk) vis = false;
    if (e === eTrans && !transArrow.visible) vis = false;
    e.div.style.visibility = vis ? 'visible' : 'hidden';
  });
}

/* ── framing ─────────────────────────────────────────────────────────────── */
function faceOnRoll(dirCam) {
  const r0 = new THREE.Vector3().crossVectors(UP, dirCam).normalize();
  const u0 = new THREE.Vector3().crossVectors(dirCam, r0).normalize();
  const phi = Math.atan2(E2v.dot(u0), E2v.dot(r0));
  return 90 - THREE.MathUtils.radToDeg(phi);
}

function applyView() {
  if (faceOn) {
    const dirCam = D.clone().negate();                     // camera upstream, looking along D
    const az = THREE.MathUtils.radToDeg(Math.atan2(dirCam.z, dirCam.x));
    const el = THREE.MathUtils.radToDeg(Math.asin(THREE.MathUtils.clamp(dirCam.y, -1, 1)));
    const t = P(panel === 'a' ? 0 : 1.2, 0, 0);
    setCameraView({
      projection: 'orthographic', azimuthDeg: az, elevationDeg: el,
      rollDeg: faceOnRoll(dirCam), heightFraction: 0.5, target: [t.x, t.y, t.z]
    });
  } else if (panel === 'a') {
    setCameraView({
      projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0,
      heightFraction: 0.80, target: [0, 0, 0]
    });
  } else {
    const t = P(4.6, 0.1, 0);
    setCameraView({
      projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0,
      heightFraction: 0.62, target: [t.x, t.y, t.z]
    });
  }
  planeHint.visible = document.getElementById('chkPlane').checked || faceOn;
  refreshLabels();
}

function setPanel(p, reframe) {
  panel = p;
  rayA.visible = (p === 'a');
  rayB.visible = (p === 'b');
  filterGroup.visible = (p === 'b');
  transGroup.visible = (p === 'b');
  leadersB.visible = (p === 'b');
  document.getElementById('btnA').classList.toggle('active', p === 'a');
  document.getElementById('btnB').classList.toggle('active', p === 'b');
  updateSelection();
  if (reframe !== false) applyView(); else refreshLabels();
}

/* ── axis / transmitted / decomposition updates ──────────────────────────── */
function updateAxisGeometry() {
  const a = axisDir();
  orient(axisArrow, a);
  orient(transArrow, a);
}

function updateSelection() {
  clearGroup(selGroup);
  const a = axisDir();
  let cosT = 1;

  if (selected < 0) {
    starArrows.forEach(s => { s.mat.opacity = 1; });
    selLabel.div.innerHTML = '';
    document.getElementById('selInfo').textContent = '';
  } else {
    const u = starArrows[selected].dir;
    cosT = u.dot(a);
    const theta = THREE.MathUtils.radToDeg(Math.acos(Math.min(1, Math.abs(cosT))));
    starArrows.forEach((s, i) => { s.mat.opacity = (i === selected) ? 1 : 0.22; });

    const parLen  = Math.abs(cosT) * L_ARROW;
    const parDir  = a.clone().multiplyScalar(Math.sign(cosT) || 1);
    const perpVec = u.clone().multiplyScalar(L_ARROW).sub(a.clone().multiplyScalar(cosT * L_ARROW));
    const perpLen = perpVec.length();

    if (parLen > 0.03) {
      const pa = buildArrow({ length: parLen, color: RED, shaftR: 0.075, headLen: 0.34, headR: 0.155 });
      orient(pa, parDir);
